ws.onopen = () => {
  // Application heartbeat: LB idle timeout is typically 60s.
  // Send ping at 25s; expect pong or close and reconnect.
  setInterval(() => {
    if (ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify({ type: 'ping', t: Date.now() }));
  }, 25000);
};
