import asyncio
# Edge holds sockets; backbone delivers once per edge, edge fans out locally.
# Bounded queue per connection: drop, don't grow.
SUBSCRIBERS: dict[str, set] = {}  # channel -> set of ws
SEQ: dict[str, int] = {}

async def on_backbone_event(channel: str, payload: bytes):
    SEQ[channel] = SEQ.get(channel, 0) + 1
    dead = []
    for ws in SUBSCRIBERS.get(channel, ()):
        if ws.queue.qsize() > 100:
            # Conflate: drop oldest, keep liveness. Trade completeness for memory.
            try: ws.queue.get_nowait()
            except asyncio.QueueEmpty: pass
            ws.dropped += 1
        try: ws.queue.put_nowait((SEQ[channel], payload))
        except asyncio.QueueFull:
            dead.append(ws)
    for ws in dead:
        await close_with_resync(ws, SEQ[channel])
